defmodule Ledger.Money.Type do
  use Ash.Type
  @ledger_currencies [:bhd, :eur, :jpy, :usd]
  @ledger_currencies_map %{"BHD" => :bhd, "EUR" => :eur, "JPY" => :jpy, "USD" => :usd}

  def storage_type, do: :map

  def cast_input(nil, _), do: {:ok, nil}
  def cast_input(%Ledger.Money{} = m, _), do: {:ok, m}

  def cast_input(map, _) when is_map(map) do
    currency = Map.get(map, :currency) || Map.get(map, "currency")
    amount = Map.get(map, :amount) || Map.get(map, "amount")

    with {:ok, c} <- resolve_currency(currency),
         {:ok, a} <- resolve_amount(amount, c) do
      Ledger.Money.new(a, c)
    end
  end

  def cast_input(str, _) when is_binary(str) do
    case String.split(str, " ") do
      [code, amount_str] ->
        with {:ok, c} <- resolve_currency(code),
             {:ok, a} <- parse_canonical_amount(amount_str, c) do
          Ledger.Money.new(a, c)
        end
      _ -> {:error, [message: "invalid money format", reason: :invalid_format]}
    end
  end

  def cast_input(_, _), do: {:error, [message: "invalid money format", reason: :invalid_format]}

  defp resolve_currency(c) when is_atom(c) and c in @ledger_currencies, do: {:ok, c}
  defp resolve_currency(c) when is_binary(c) do
    case Map.get(@ledger_currencies_map, String.upcase(c)) do
      nil -> {:error, [message: "unknown currency", reason: :unknown_currency, currency: c]}
      found -> {:ok, found}
    end
  end
  defp resolve_currency(c), do: {:error, [message: "unknown currency", reason: :unknown_currency, currency: c]}

  defp resolve_amount(a, _) when is_integer(a), do: {:ok, a}
  defp resolve_amount(a, _) when is_binary(a) and a =~ ~r/^-?[0-9]+$/, do: {:ok, String.to_integer(a)}
  defp resolve_amount(a, _) when is_binary(a) and a =~ ~r/^-?[0-9]+\.[0-9]+$/, do: {:error, [message: "amount must be a whole number of minor units", reason: :fractional_minor_units]}
  defp resolve_amount(_, _), do: {:error, [message: "invalid money format", reason: :invalid_format]}

  defp parse_canonical_amount(amount_str, currency) do
    exp = Ledger.Money.exponent(currency)
    case amount_str =~ ~r/^-?[0-9]+$/ do
      true ->
        if exp != 0, do: {:error, [message: "invalid money format", reason: :invalid_format]}, else: {:ok, String.to_integer(amount_str)}
      false ->
        case String.split(amount_str, ".") do
          [int_part, frac_part] ->
             if String.length(frac_part) != exp, do: {:error, [message: "invalid money format", reason: :invalid_format]}, else: {:ok, String.to_integer(int_part <> frac_part)}
          _ -> {:error, [message: "invalid money format", reason: :invalid_format]}
        end
    end
  end

  def cast_stored(map, _) when is_map(map) do
    # Assume stored as %{"currency" => ..., "amount" => ...} or similar
    # Simple check for round trip
    case cast_input(map, nil) do
      {:ok, m} -> {:ok, m}
      _ -> {:error, [message: "invalid money format", reason: :invalid_format]}
    end
  end
  def cast_stored(_, _), do: {:error, [message: "invalid money format", reason: :invalid_format]}

  def dump_to_native(%Ledger.Money{currency: c, amount: a}, _), do: {:ok, %{currency: Atom.to_string(c), amount: a}}
  def dump_to_native(nil, _), do: {:ok, nil}
  def dump_to_native(_, _), do: :error

  def apply_constraints(money, opts, _) do
    # Currency
    if opts[:currencies] && money.currency not in opts[:currencies] do
      {:error, [message: "currency is not allowed", reason: :currency_not_allowed, currency: money.currency]}
    else
      # Multiple of
      if opts[:multiple_of] && rem(money.amount, opts[:multiple_of]) != 0 do
         {:error, [message: "must be a multiple of %{multiple_of} minor units", reason: :not_multiple_of, multiple_of: opts[:multiple_of]]}
      else
        # Min/Max
        with {:ok, min_val} <- get_bound(opts[:min], money.currency),
             {:ok, max_val} <- get_bound(opts[:max], money.currency) do
          if min_val && Ledger.Money.compare(money, min_val) == :lt do
            {:error, [message: "must be greater than or equal to %{min}", reason: :below_min, min: Ledger.Money.to_string(min_val)]}
          else
            if max_val && Ledger.Money.compare(money, max_val) == :gt do
              {:error, [message: "must be less than or equal to %{max}", reason: :above_max, max: Ledger.Money.to_string(max_val)]}
            else
              {:ok, money}
            end
          end
        rescue
          ArgumentError -> {:error, [message: "cannot compare money in different currencies", reason: :currency_mismatch]}
        end
      end
    end
  end

  defp get_bound(nil, _), do: {:ok, nil}
  defp get_bound(bound, currency) do
    case cast_input(bound, nil) do
      {:ok, %Ledger.Money{currency: ^currency} = m} -> {:ok, m}
      {:ok, %Ledger.Money{}} -> {:error, :currency_mismatch}
      _ -> {:ok, nil}
    end
  end
end

