  def storage_type, do: :map

  def cast_input(input, _), do: Ledger.Money.Type.cast_input(input, nil) |> case do
    {:ok, %Ledger.Money{currency: :usd} = m} -> 
      if m.amount >= 0 and m.amount <= 1000000, do: {:ok, m}, else: {:error, [message: "out of range", reason: :invalid_format]}
