  def price_for!(unit_price, units), do: Ash.read_one!(Ledger.Billing.Invoice, action: :price_for, arguments: %{unit_price: unit_price, units: units})

  def record_payment(params), do: Ash.Changeset.for_create(Ledger.Billing.Payment, :record, params) |> Ash.create()
  def record_payment!(params), do: Ash.Changeset.for_create(Ledger.Billing.Payment, :record, params) |> Ash.create!()
end
